function validate([citations]) {
  if (citations.length < 1 || citations.length > 5000) return 'citations needs 1 to 5000 values.';
  if (citations.some(c => !Number.isInteger(c) || c < 0 || c > 1000)) return 'Each count is a whole number from 0 to 1000.';
  return null;
}

