function hIndex(citations) {
  const sorted = [...citations].sort((a, b) => b - a);
  let h = 0;

  for (let i = 0; i < sorted.length; i++) {
    const papers = i + 1;
    if (sorted[i] < papers) {
      break;
    }
    h = papers;
  }
  return h;
}

brute:
function hIndex(citations) {
  for (let h = citations.length; h > 0; h--) {
    if (citations.filter(c => c >= h).length >= h) return h;
  }
  return 0;
}

