function generate(rand, size) {
  if (size === 'large') return [Array.from({ length: 2000 }, () => Math.floor(rand() * 1001))];
  const n = 1 + Math.floor(rand() * 8);
  const top = rand() < 0.15 ? 0 : Math.floor(rand() * 12);
  return [Array.from({ length: n }, () => Math.floor(rand() * (top + 1)))];
}
